function AdminPanel({ candidateForm, setCandidateForm, onSave }) {
  return (
    <div>
      <h2>Add / Edit Candidate</h2>

      <input
        type="text"
        placeholder="Full Name"
        value={candidateForm.name}
        onChange={(e) =>
          setCandidateForm({ ...candidateForm, name: e.target.value })
        }
      />
      <br /><br />

      <input
        type="text"
        placeholder="Candidacy Position"
        value={candidateForm.position}
        onChange={(e) =>
          setCandidateForm({ ...candidateForm, position: e.target.value })
        }
      />
      <br /><br />

      <textarea
        placeholder="Description"
        value={candidateForm.description}
        onChange={(e) =>
          setCandidateForm({ ...candidateForm, description: e.target.value })
        }
      />
      <br /><br />

      <input
        type="file"
        onChange={(e) =>
          setCandidateForm({
            ...candidateForm,
            image: e.target.files[0],
          })
        }
      />
      <br /><br />

      <button onClick={onSave}>
        Save Candidate
      </button>
    </div>
  );
}

export default AdminPanel;
